const key=(latex,insert=latex,tooltip='')=>({latex,insert,tooltip,class:'small'});
const letter=(c)=>({latex:c,insert:c,shift:{latex:c.toUpperCase(),insert:c.toUpperCase()}});
const fraction=key('\\frac{a}{b}','\\frac{#@}{#?}','کسر');
const power=key('x^n','#@^{#?}','توان');
const root=key('\\sqrt{x}','\\sqrt{#0}','ریشه');
